from __future__ import annotations

import sys
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent
REPOSITORY_DIR = BASE_DIR.parent.parent
if str(REPOSITORY_DIR) not in sys.path:
    sys.path.insert(0, str(REPOSITORY_DIR))

from pytrans import TranspileError, transpile_native_cpp

INPUT_PATH = BASE_DIR / "input.py"
OUTPUT_PATH = BASE_DIR / "output.cpp"


def comment_source(source: str) -> str:
    lines = source.splitlines()
    header = (
        "// Generated by pytrans.\n"
        "// This is a deterministic, rule-based translation from Python to C++.\n"
        "// No AI or network access is used during translation.\n"
        f"// Source: {INPUT_PATH.name}"
    )
    body = "\n".join((f"// {line}" + (" [line end]" if line.rstrip().endswith("\\") else "")) if line else "//" for line in lines)
    footer = f"// End of {INPUT_PATH.name}"
    return "\n".join((header, body, footer, "")) + "\n"


def main() -> int:
    try:
        source = INPUT_PATH.read_text(encoding="utf-8")
        output = comment_source(source) + transpile_native_cpp(source, str(INPUT_PATH))
        OUTPUT_PATH.write_text(output, encoding="utf-8")
    except (OSError, TranspileError) as error:
        print(f"pytrans: {error}")
        return 1
    print(f"generated: {OUTPUT_PATH}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
